    // ==========================================
    // SECTION 3: IMPORT LOGIC (with deduplication)
    // ==========================================
    function runImportV2() {
        // Check if system is ready
        if (typeof window.clients === 'undefined' || 
            typeof window.financialTransactions === 'undefined' || 
            typeof saveData !== 'function') {
            console.log('⏳ Import V2: Waiting for system...');
            setTimeout(runImportV2, 2000);
            return;
        }
        
        // Check if already imported
        var importKey = 'superpro_import_v2_done';
        if (localStorage.getItem(importKey) === 'true') {
            console.log('✅ Import V2: Already done, skipping.');
            initReports();
            return;
        }
        
        console.log('🚀 Import V2: Starting import...');
        
        var addedInvoices = 0;
        var addedClients = 0;
        var duplicatesSkipped = 0;
        
        // --- 3a. Add NEW CLIENTS ---
        var existingNames = new Set();
        (window.clients || []).forEach(function(c) {
            existingNames.add((c.name || '').toLowerCase().trim());
        });
        
        NEW_CLIENTS.forEach(function(name) {
            if (!existingNames.has(name.toLowerCase().trim())) {
                var clientId = 'CLT-INV-' + Date.now() + '-' + Math.random().toString(36).substr(2, 5);
                window.clients.push({
                    id: clientId,
                    name: name,
                    phone: '',
                    email: '',
                    address: '',
                    notes: 'مستورد من فواتير Excel',
                    createdAt: new Date().toISOString()
                });
                addedClients++;
                existingNames.add(name.toLowerCase().trim());
            }
        });
        
        // --- 3b. Add INVOICES to financialTransactions ---
        var existingInvIds = new Set();
        (window.financialTransactions || []).forEach(function(t) {
            if (t.id) existingInvIds.add(t.id.toLowerCase().trim());
        });
        
        INVOICE_DATA.forEach(function(inv) {
            var invId = (inv.id || '').toLowerCase().trim();
            if (existingInvIds.has(invId)) {
                duplicatesSkipped++;
                return;
            }
            window.financialTransactions.push({
                id: inv.id,
                type: 'فاتورة',
                clientName: inv.clientName,
                description: inv.description,
                date: inv.date,
                amount: inv.amount,
                status: inv.status,
                notes: inv.notes
            });
            addedInvoices++;
            existingInvIds.add(invId);
        });
        
        // --- 3c. Deduplicate ALL data ---
        deduplicateAll();
        
        // --- 3d. Save ---
        try {
            saveData();
            console.log('💾 Import V2: Data saved to Firebase');
        } catch(e) {
            console.error('Save error:', e);
        }
        
        // Mark as done
        localStorage.setItem(importKey, 'true');
        
        console.log('✅ Import V2 Complete: ' + addedInvoices + ' invoices, ' + addedClients + ' clients, ' + duplicatesSkipped + ' duplicates skipped');
        
        if (typeof showToast === 'function') {
            showToast('✅ تم استيراد ' + addedInvoices + ' فاتورة و ' + addedClients + ' عميل جديد', 'success');
        }
        
        initReports();
    }
    
    // ==========================================
    // SECTION 4: DEDUPLICATION ENGINE
    // ==========================================
    function deduplicateAll() {
        console.log('🧹 Deduplication: Starting...');
        
        // Deduplicate clients by name (case-insensitive)
        if (window.clients && window.clients.length > 0) {
            var seen = {};
            var unique = [];
            window.clients.forEach(function(c) {
                var key = (c.name || '').toLowerCase().trim();
                if (key && !seen[key]) {
                    seen[key] = true;
                    unique.push(c);
                }
            });
            var removed = window.clients.length - unique.length;
            if (removed > 0) {
                window.clients = unique;
                console.log('  Clients: removed ' + removed + ' duplicates');
            }
        }
        
        // Deduplicate contracts by id
        if (window.contracts && window.contracts.length > 0) {
            var seen = {};
            var unique = [];
            window.contracts.forEach(function(c) {
                var key = (c.number || c.id || '').toLowerCase().trim();
                if (!key || !seen[key]) {
                    if (key) seen[key] = true;
                    unique.push(c);
                }
            });
            var removed = window.contracts.length - unique.length;
            if (removed > 0) {
                window.contracts = unique;
                console.log('  Contracts: removed ' + removed + ' duplicates');
            }
        }
        
        // Deduplicate dailyWork by id
        if (window.dailyWork && window.dailyWork.length > 0) {
            var seen = {};
            var unique = [];
            window.dailyWork.forEach(function(w) {
                var key = (w.bookingNo || w.id || '').toLowerCase().trim();
                if (!key || !seen[key]) {
                    if (key) seen[key] = true;
                    unique.push(w);
                }
            });
            var removed = window.dailyWork.length - unique.length;
            if (removed > 0) {
                window.dailyWork = unique;
                console.log('  DailyWork: removed ' + removed + ' duplicates');
            }
        }
        
        // Deduplicate dailyExpenses by id
        if (window.dailyExpenses && window.dailyExpenses.length > 0) {
            var seen = {};
            var unique = [];
            window.dailyExpenses.forEach(function(e) {
                var key = (e.expenseNo || e.id || '').toLowerCase().trim();
                if (!key || !seen[key]) {
                    if (key) seen[key] = true;
                    unique.push(e);
                }
            });
            var removed = window.dailyExpenses.length - unique.length;
            if (removed > 0) {
                window.dailyExpenses = unique;
                console.log('  DailyExpenses: removed ' + removed + ' duplicates');
            }
        }
        
        // Deduplicate monthlyExpenses by id
        if (window.monthlyExpenses && window.monthlyExpenses.length > 0) {
            var seen = {};
            var unique = [];
            window.monthlyExpenses.forEach(function(e) {
                var key = (e.expenseNo || e.id || '').toLowerCase().trim();
                if (!key || !seen[key]) {
                    if (key) seen[key] = true;
                    unique.push(e);
                }
            });
            var removed = window.monthlyExpenses.length - unique.length;
            if (removed > 0) {
                window.monthlyExpenses = unique;
                console.log('  MonthlyExpenses: removed ' + removed + ' duplicates');
            }
        }
        
        // Deduplicate financialTransactions by id
        if (window.financialTransactions && window.financialTransactions.length > 0) {
            var seen = {};
            var unique = [];
            window.financialTransactions.forEach(function(t) {
                var key = (t.id || '').toLowerCase().trim();
                if (!key || !seen[key]) {
                    if (key) seen[key] = true;
                    unique.push(t);
                }
            });
            var removed = window.financialTransactions.length - unique.length;
            if (removed > 0) {
                window.financialTransactions = unique;
                console.log('  FinancialTransactions: removed ' + removed + ' duplicates');
            }
        }
        
        console.log('🧹 Deduplication: Complete');
    }
    
    // ==========================================
    // SECTION 5: DAILY & MONTHLY REPORTS
    // ==========================================
    function initReports() {
        console.log('📊 Reports: Initializing...');
        
        // Override loadReports to add daily/monthly report tabs
        var origLoadReports = window.loadReports;
        
        window.loadReports = function() {
            var section = document.getElementById('reports');
            if (!section) return;
            
            section.innerHTML = getReportsPageHtml();
            
            // Set default date to today
            var today = new Date().toISOString().split('T')[0];
            var dateInput = document.getElementById('v2-daily-date');
            if (dateInput) dateInput.value = today;
            
            // Set default month
            var monthInput = document.getElementById('v2-monthly-month');
            if (monthInput) monthInput.value = today.substring(0, 7);
            
            // Generate initial reports
            generateDailyReport();
            generateMonthlyReport();
            
            setupReportButtons();
        };
        
        console.log('📊 Reports: Ready');
    }
    
