    // Download PDF using html2pdf.js
    function downloadPDF(filename, html) {
        // Create temporary visible container
        var overlay = document.createElement('div');
        overlay.style.cssText = 'position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,0.7);z-index:99999;display:flex;align-items:center;justify-content:center';
        overlay.innerHTML = '<div style="background:white;padding:20px;border-radius:10px;text-align:center"><i class="fas fa-spinner fa-spin" style="font-size:30px;color:#0d6efd"></i><p style="margin-top:10px">جاري إنشاء PDF...</p></div>';
        document.body.appendChild(overlay);
        
        var container = document.createElement('div');
        container.style.cssText = 'position:fixed;top:0;left:0;width:210mm;background:white;z-index:99998;padding:20px;font-family:Arial,sans-serif;direction:rtl;font-size:11px;overflow:visible';
        container.innerHTML = '<div style="text-align:center;margin-bottom:15px"><h2>SuperPro</h2><h3>' + filename.replace(/_/g,' ') + '</h3><p>' + new Date().toLocaleDateString('ar-SA') + '</p></div>' + html;
        
        // Fix table styles
        var tables = container.querySelectorAll('table');
        tables.forEach(function(t) {
            t.style.cssText = 'width:100%;border-collapse:collapse;margin:8px 0;font-size:10px';
            t.querySelectorAll('th,td').forEach(function(cell) {
                cell.style.cssText = 'border:1px solid #333;padding:4px 6px;text-align:right';
            });
            t.querySelectorAll('th').forEach(function(th) {
                th.style.cssText = 'border:1px solid #333;padding:4px 6px;text-align:right;background:#333;color:white';
            });
        });
        
        // Fix badges
        container.querySelectorAll('.badge').forEach(function(b) {
            b.style.cssText = 'padding:2px 6px;border-radius:3px;color:white;font-size:9px';
            if (b.classList.contains('bg-success')) b.style.background = '#198754';
            else if (b.classList.contains('bg-danger')) b.style.background = '#dc3545';
        });
        
        // Fix cards
        container.querySelectorAll('.card').forEach(function(c) {
            c.style.cssText = 'border:1px solid #ddd;padding:8px;margin:3px;border-radius:5px;text-align:center;display:inline-block;min-width:100px';
            if (c.classList.contains('bg-primary')) { c.style.background = '#0d6efd'; c.style.color = 'white'; }
            if (c.classList.contains('bg-success')) { c.style.background = '#198754'; c.style.color = 'white'; }
            if (c.classList.contains('bg-danger')) { c.style.background = '#dc3545'; c.style.color = 'white'; }
            if (c.classList.contains('bg-warning')) { c.style.background = '#ffc107'; c.style.color = '#333'; }
            if (c.classList.contains('bg-info')) { c.style.background = '#0dcaf0'; c.style.color = '#333'; }
        });
        
        // Fix rows
        container.querySelectorAll('.row').forEach(function(r) {
            r.style.cssText = 'display:flex;flex-wrap:wrap;gap:3px;margin-bottom:8px';
        });
        
        document.body.appendChild(container);
        
        // Use html2pdf
        if (typeof html2pdf === 'undefined') {
            var script = document.createElement('script');
            script.src = 'https://cdnjs.cloudflare.com/ajax/libs/html2pdf.js/0.10.1/html2pdf.bundle.min.js';
            script.onload = function() { doGenerate(); };
            document.head.appendChild(script);
        } else {
            doGenerate();
        }
        
        function doGenerate() {
            html2pdf().set({
                margin: [10,5,10,5],
                filename: filename + '.pdf',
                image: { type: 'jpeg', quality: 0.95 },
                html2canvas: { scale: 2, useCORS: true, scrollY: 0, windowWidth: container.scrollWidth },
                jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' },
                pagebreak: { mode: ['avoid-all', 'css', 'legacy'] }
            }).from(container).save().then(function() {
                document.body.removeChild(container);
                document.body.removeChild(overlay);
                if (typeof showToast === 'function') showToast('✅ تم تحميل PDF بنجاح', 'success');
            }).catch(function(err) {
                console.error('PDF error:', err);
                document.body.removeChild(container);
                document.body.removeChild(overlay);
                if (typeof showToast === 'function') showToast('❌ خطأ في إنشاء PDF', 'error');
            });
        }
    }
    
    // Excel export helper
    function exportExcel(data, sheetName, fileName) {
        if (typeof XLSX === 'undefined') {
            var script = document.createElement('script');
            script.src = 'https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js';
            script.onload = function() { doExport(); };
            document.head.appendChild(script);
        } else {
            doExport();
        }
        function doExport() {
            var wb = XLSX.utils.book_new();
            var ws = XLSX.utils.json_to_sheet(data);
            XLSX.utils.book_append_sheet(wb, ws, sheetName);
            XLSX.writeFile(wb, fileName);
            if (typeof showToast === 'function') showToast('✅ تم تصدير Excel', 'success');
        }
    }
    
