    window.exportDailyExcel = function() {
        var dateStr = document.getElementById('v2-daily-date').value;
        var invoices = getInvoicesForDate(dateStr);
        var data = invoices.map(function(i,idx) {
            return {'#': idx+1, 'رقم الفاتورة': i.id, 'العميل': i.clientName, 'التاريخ': i.date, 'المبلغ': i.amount, 'الحالة': i.status};
        });
        exportExcel(data, 'التقرير اليومي', 'التقرير_اليومي_' + dateStr + '.xlsx');
    };
    
